import {PDFDocument,StandardFonts} from 'pdf-lib';
export async function capacityPDF(count=250){const pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica);for(let i=0;i<count;i++){const page=pdf.addPage();page.drawText('Capacity page '+(i+1),{font,size:14,x:40,y:760});for(let line=0;line<15;line++)page.drawText('Page '+(i+1)+', line '+(line+1)+': Long documents keep their source, fields and independent backups.',{font,size:9,x:40,y:720-line*22})}pdf.getForm().createTextField('Final page').addToPage(pdf.getPage(count-1),{x:40,y:320,width:200,height:25,borderWidth:0});return pdf.save()}
